-- Set by `pack_radio.py --no-lock`: the payload key in the clear, which makes
-- this build run on any server. Empty in a locked build.
local OPEN = ''

-- ------------------------------------------------------------------
--  Payload
-- ------------------------------------------------------------------

--- ac.checksumSHA256 may hand back 32 raw bytes or a 64-char hex string
--- depending on build, so normalise to lowercase hex either way.
local function shaHex(value)
  local digest = ac.checksumSHA256(value)
  if not digest then return nil end
  if #digest == 64 then return digest:lower() end
  return (digest:gsub('.', function (char)
    return string.format('%02x', string.byte(char))
  end)):lower()
end

local function deriveKey(secret)
  local key = shaHex(SALT .. '|' .. secret)
  if not key then return nil end
  for _ = 1, ITER do
    key = shaHex(key .. SALT)
  end
  return key
end

--- Every shape the running server's identity might take. Whichever one this
--- build was locked to will match; the rest simply fail to unwrap.
local function serverIdents()
  local ip   = ac.getServerIP and ac.getServerIP() or ''
  local name = ac.getServerName and ac.getServerName() or ''
  local port = ac.getServerPortTCP and ac.getServerPortTCP() or 0
  local list = {}
  if ip ~= '' then
    list[#list + 1] = ip
    if port and port > 0 then list[#list + 1] = ip .. ':' .. port end
  end
  if name ~= '' then
    list[#list + 1] = name
    if ip ~= '' then list[#list + 1] = ip .. '|' .. name end
  end
  return list
end

--- Unwraps the payload key using the server identity, rather than any secret
--- stored in the server's config.
local function unwrapKey()
  -- Unlocked build: the key ships with the file, no server check at all.
  if OPEN ~= '' and shaHex(OPEN .. '#' .. BLOB) == TAG then return OPEN end

  local period = math.floor(os.time() / PERIOD)
  for _, ident in ipairs(serverIdents()) do
    local derived = deriveKey(ident .. '@' .. period)
    if derived then
      for _, lock in ipairs(LOCKS) do
        local candidate = {}
        for i = 1, #lock / 2 do
          local wrapped = tonumber(lock:sub(i * 2 - 1, i * 2), 16)
          local mask = tonumber(derived:sub(i * 2 - 1, i * 2), 16)
          candidate[i] = string.format('%02x', (wrapped - mask) % 256)
        end
        candidate = table.concat(candidate)
        if shaHex(candidate .. '#' .. BLOB) == TAG then return candidate end
      end
    end
  end
  return nil
end

local function decrypt()
  local key = unwrapKey()
  if not key then return nil end

  local out, blockIndex, keystream = {}, -1, nil
  for i = 1, #BLOB / 2 do
    local block = math.floor((i - 1) / 32)
    if block ~= blockIndex then
      blockIndex = block
      keystream = shaHex(key .. ':' .. block)
    end
    local offset = ((i - 1) % 32) * 2
    local keyByte = tonumber(keystream:sub(offset + 1, offset + 2), 16)
    local cipherByte = tonumber(BLOB:sub(i * 2 - 1, i * 2), 16)
    out[i] = string.char((cipherByte - keyByte) % 256)
  end
  return table.concat(out)
end

local function parseStations(plain)
  local list = {}
  for line in plain:gmatch('[^\n]+') do
    local id, frequency, name, urls = line:match('^([^|]*)|([^|]*)|([^|]*)|(.*)$')
    if id then
      local entry = { id = id, frequency = frequency, name = name, urls = {} }
      for url in urls:gmatch('[^\t]+') do
        entry.urls[#entry.urls + 1] = url
      end
      if #entry.urls > 0 then list[#list + 1] = entry end
    end
  end
  return list
end

local stations = {}
local licensed = false

do
  local plain = decrypt()
  if plain then
    stations = parseStations(plain)
    licensed = #stations > 0
  end
end

-- Pin the two headline frequencies to their real live broadcasts. Prefer MP3
-- for HOT 97 because it starts more reliably in Windows Media Foundation than
-- the AAC+ Shoutcast variant. POWER 105.1 is supplied live by iHeart/Revma.
-- These public redirects select a healthy edge server for each joining player.
local LIVE_STREAMS = {
  power1051 = {
    'https://stream.revma.ihrhls.com/zc1481'
  },
  hot97 = {
    'https://playerservices.streamtheworld.com/api/livestream-redirect/WQHTFM.mp3',
    'https://playerservices.streamtheworld.com/api/livestream-redirect/WQHTFM_SC',
    'https://playerservices.streamtheworld.com/api/livestream-redirect/WQHTFMAAC_SC'
  }
}
for _, station in ipairs(stations) do
  if LIVE_STREAMS[station.id] then
    station.urls = LIVE_STREAMS[station.id]
  end
end

-- Start every joining player on HOT 97's MP3 feed. MP3 avoids the AAC decoder
-- failure reported by CSP as `MMF error: 4` on affected Windows installations.
local DEFAULT_STATION = 1
for index, station in ipairs(stations) do
  if station.id == 'hot97' then
    DEFAULT_STATION = index
    break
  end
end

-- ------------------------------------------------------------------
--  Radio
-- ------------------------------------------------------------------

-- Seconds a stream gets to produce audio before we fall through to its backup.
local CONNECT_TIMEOUT = 9
-- Full passes through a station's URL list before giving up on it, so a dead
-- station can't sit there reconnecting forever in the background.
local MAX_PASSES = 3

local selected = DEFAULT_STATION
local urlIndex = 1
local passes = 0
local volume = 0.55
local muted = false
local powered = licensed
local player = nil
local status = licensed and 'STARTING' or 'LOCKED'
local statusDetail = licensed and 'Loading CSP native audio'
  or 'This server is not authorised to run this radio'
local statusTimer = 0
local sinceTune = 0
local toastShown = false
local autoStartTimer = 0
local mediaCheckStarted = false
local AUTO_START_DELAY = 1.0

local function currentStation()
  return stations[selected]
end

-- CSP's own in-car radio - the dash / Android Auto app, driven by SmallTweaks -
-- publishes its state in this shared struct. The two players are completely
-- independent, so without reading it both stream at once as soon as you sit in
-- a car with a working head unit. The layout has to match CSP's declaration
-- exactly or every read is garbage; pcall so a CSP build without it cannot take
-- the radio down.
local carRadio = nil
pcall(function ()
  carRadio = ac.connect({
    ac.StructItem.key('radioState'),
    stationsPhase = ac.StructItem.int32(),
    metadataPhase = ac.StructItem.int32(),
    playing = ac.StructItem.int32(),
    title = ac.StructItem.string(512),
    artist = ac.StructItem.string(512),
    artwork = ac.StructItem.string(512),
    timePlayed = ac.StructItem.int16(),
    timeTotal = ac.StructItem.int16(),
    status = ac.StructItem.uint8(),
    paused = ac.StructItem.boolean(),
    awoken = ac.StructItem.boolean(),
    volume = ac.StructItem.float(),
  }, false, ac.SharedNamespace.Shared)
end)

-- True while the car's own radio is playing. Mutes rather than stops, so this
-- one picks straight back up when the dash radio is switched off.
local carRadioPlaying = false

local function applyVolume()
  if player then
    player:setVolume(volume)
    player:setMuted(muted or not powered or carRadioPlaying)
  end
end

local function shownStatus()
  return carRadioPlaying and 'STANDBY' or status
end

local function shownDetail()
  return carRadioPlaying and 'Car radio is playing' or statusDetail
end

local function claimAudio()
  if carRadio ~= nil and carRadio.playing ~= 0 then
    carRadio.playing = 0
  end
  if carRadioPlaying and player and powered then
    player:play()
  end
  carRadioPlaying = false
end

local function tune(index, urlIdx)
  if not licensed then return end
  selected = ((index - 1) % #stations) + 1
  local station = currentStation()
  urlIndex = urlIdx or 1

  if not ui.MediaPlayer.supported() then
    status = 'UNAVAILABLE'
    statusDetail = 'CSP native media playback is not supported on this PC'
    powered = false
    return
  end

  if not player then
    -- Send radio audio straight to the Windows default device. Routing a live
    -- Media Foundation stream through AC/FMOD can report playback while staying
    -- silent on some CSP/audio-device combinations.
    player = ui.MediaPlayer(nil, { rawOutput = true, use3D = false })
  end

  powered = true
  muted = false
  status = 'TUNING'
  statusDetail = 'Opening ' .. station.name
  player:setSource(station.urls[urlIndex])
  player:setAutoPlay(true)
  applyVolume()
  player:play()
  -- The car radio may already hold the audio - the watcher in script.update
  -- only reacts to changes, so a player created after it started would
  -- otherwise come up playing over the top of it.
  if carRadioPlaying then
    player:pause()
  end
  statusTimer = 0
  sinceTune = 0
end

local function stopRadio()
  powered = false
  status = 'STOPPED'
  statusDetail = 'Radio off'
  if player then
    player:pause()
    player:setMuted(true)
  end
end

local function togglePower()
  if powered then
    stopRadio()
  else
    passes = 0
    claimAudio()
    tune(selected, 1)
  end
end

local COLOR_SCREEN = rgbm(0.018, 0.028, 0.055, 0.98)
local COLOR_PANEL = rgbm(0.035, 0.065, 0.105, 0.96)
local COLOR_CYAN = rgbm(0.05, 0.90, 1.00, 1)
local COLOR_MAGENTA = rgbm(1.00, 0.10, 0.62, 1)
local COLOR_LIME = rgbm(0.28, 1.00, 0.58, 1)
local COLOR_MUTED = rgbm(0.48, 0.60, 0.72, 1)

local function stationStep(direction)
  if #stations == 0 then return end
  passes = 0
  claimAudio()
  tune(selected + direction, 1)
end

-- ------------------------------------------------------------------
--  Display
-- ------------------------------------------------------------------

-- Artwork drawn across the whole display. CSP accepts a URL here as well as a
-- path relative to the AC root, and loads it asynchronously; until it arrives,
-- and if it never does, the procedural backdrop below stands in. The image is
-- the screen area of the BTA dashboard render, cropped and served as an 87 KB
-- JPEG because every joining player fetches it.
local ARTWORK_URL =
  'https://raw.githubusercontent.com/richbreadyy/bta-assets/main/bta_radio_display.jpg?v=5144342'
-- Width divided by height of that image. The display box is sized to match so
-- the artwork is never stretched.
local ARTWORK_ASPECT = 3.443

local BAR_COUNT = 22
local DISPLAY_MIN_HEIGHT, DISPLAY_MAX_HEIGHT = 76, 300
local uiTime = 0

--- Advanced from script.update so the animation runs on wall time rather than
--- frame count.
local function tickDisplay(dt)
  uiTime = uiTime + dt
end

--- One bank of neon equaliser columns. Idle and dim when nothing is actually
--- playing, so a dead stream reads as dead instead of faking a signal.
local function drawBars(origin, size, live)
  local barWidth = size.x / BAR_COUNT
  for i = 0, BAR_COUNT - 1 do
    local phase = uiTime * 5.5 + i * 0.5
    local amp = live
      and (0.18 + 0.82 * math.abs(math.sin(phase) * math.cos(phase * 0.41 + 1.3)))
      or 0.05
    local barHeight = size.y * amp
    local x = origin.x + i * barWidth
    local mid = origin.y + size.y / 2
    local t = i / (BAR_COUNT - 1)
    local color = rgbm(0.05 + t * 0.55, 0.88 - t * 0.42, 1.0, live and 0.92 or 0.35)
    ui.drawRectFilled(vec2(x + 1, mid - barHeight / 2),
                      vec2(x + barWidth - 1, mid + barHeight / 2), color, 2)
  end
end

--- The speaker cones either side of the wordmark.
local function drawSpeaker(center, radius, live)
  local pulse = live and (1 + 0.05 * math.sin(uiTime * 7)) or 1
  ui.drawCircleFilled(center, radius * 0.62 * pulse, rgbm(0.04, 0.05, 0.09, 0.96), 48)
  ui.drawCircle(center, radius * pulse, COLOR_MAGENTA, 64, 2.5)
  ui.drawCircle(center, radius * 0.74 * pulse, rgbm(0.60, 0.18, 0.90, 0.85), 64, 1.5)
  ui.drawCircle(center, radius * 0.34 * pulse, rgbm(0.16, 0.75, 1.00, 0.9), 48, 1.5)
  ui.drawCircleFilled(center, radius * 0.10 * pulse, rgbm(0.9, 0.5, 1.0, 0.9), 24)
end

--- Big BTA wordmark. DirectWrite gives a real display face; if the font is not
--- installed or the call is unavailable, fall back to plain text rather than
--- letting an error take the whole panel down on a live server.
local function drawWordmark(center, height)
  local drawn = pcall(function()
    ui.pushDWriteFont('Impact')
    ui.beginOutline()
    ui.dwriteDrawTextClipped('BTA', height,
      center - vec2(230, height * 0.75), center + vec2(230, height * 0.75),
      ui.Alignment.Center, ui.Alignment.Center, false, rgbm(1, 1, 1, 1))
    ui.endOutline(rgbm(0.55, 0.15, 0.95, 0.9), 1.6)
    ui.popDWriteFont()
  end)
  if not drawn then
    ui.setCursor(center - vec2(16, 8))
    ui.textColored('BTA', rgbm(1, 1, 1, 1))
  end
end

--- The whole dashboard display: artwork or procedural backdrop, equaliser
--- banks, speakers, wordmark, and the now-playing line across the bottom.
local function drawDisplay(origin, size, station, live)
  local far = origin + size
  local hasArt = ARTWORK_URL ~= '' and ui.isImageReady(ARTWORK_URL)

  if hasArt then
    -- The artwork already carries the equaliser, the speakers and the
    -- wordmark, so none of the procedural furniture is drawn over it.
    ui.drawImage(ARTWORK_URL, origin, far, rgbm(1, 1, 1, 1),
                 vec2(0, 0), vec2(1, 1), ui.ImageFit.Stretch)
  else
    -- Night-city backdrop: deep blue to violet, with a skyline of blocks.
    ui.drawRectFilledMultiColor(origin, far,
      rgbm(0.03, 0.05, 0.12, 1), rgbm(0.07, 0.03, 0.14, 1),
      rgbm(0.12, 0.03, 0.20, 1), rgbm(0.02, 0.06, 0.16, 1))
    local baseline = far.y - 26
    for i = 0, 21 do
      local w = size.x / 22
      local x = origin.x + i * w
      local h = 26 + ((i * 37) % 53) + ((i * 13) % 29)
      ui.drawRectFilled(vec2(x + 2, baseline - h), vec2(x + w - 2, baseline),
                        rgbm(0.06, 0.08, 0.18, 0.85), 1)
    end

    local mid = origin.y + size.y * 0.46
    local bankWidth = size.x * 0.19
    drawBars(vec2(origin.x + 16, mid - 42), vec2(bankWidth, 84), live)
    drawBars(vec2(far.x - 16 - bankWidth, mid - 42), vec2(bankWidth, 84), live)

    local speakerRadius = math.min(46, size.y * 0.20)
    drawSpeaker(vec2(origin.x + bankWidth + 62, mid), speakerRadius, live)
    drawSpeaker(vec2(far.x - bankWidth - 62, mid), speakerRadius, live)

    drawWordmark(vec2(origin.x + size.x / 2, mid), math.min(86, size.y * 0.38))
  end

  ui.drawRect(origin, far, rgbm(0.10, 0.38, 0.55, 1), 14, 0, 1)

  -- A 54px scrim over an 80px display buries the artwork, so only overlay the
  -- now-playing text when the display is tall enough to carry it.
  if size.y < 120 then return false end

  ui.drawRectFilled(vec2(origin.x, far.y - 54), far, rgbm(0, 0, 0, 0.62), 0)
  ui.setCursor(vec2(origin.x + 20, far.y - 48))
  ui.textColored('NOW PLAYING', COLOR_MAGENTA)
  ui.setCursor(vec2(origin.x + 20, far.y - 28))
  ui.textColored(station.frequency, COLOR_CYAN)
  ui.sameLine()
  ui.textColored('  ' .. station.name, rgbm(1, 1, 1, 1))
  ui.setCursor(vec2(origin.x + size.x * 0.5, far.y - 28))
  ui.textColored(shownStatus(), shownStatus() == 'PLAYING' and COLOR_LIME or COLOR_MUTED)
  ui.sameLine()
  ui.textColored('   ' .. shownDetail(), COLOR_MUTED)
  return true
end

local function radioUI()
  local screenStart = ui.getCursor()
  local screenWidth = ui.availableSpaceX()
  -- Track the window rather than a fixed height, so the frame still fits when
  -- the panel is resized.
  local screenHeight = math.max(180, ui.availableSpaceY() - 4)
  ui.drawRectFilled(screenStart, screenStart + vec2(screenWidth, screenHeight), COLOR_SCREEN, 14)
  ui.drawRect(screenStart, screenStart + vec2(screenWidth, screenHeight), rgbm(0.10, 0.38, 0.55, 1), 14, 0, 1)

  ui.offsetCursor(vec2(14, 12))
  ui.textColored('B T A', COLOR_CYAN)
  ui.sameLine()
  ui.textColored('   URBAN DRIVE RADIO', COLOR_MAGENTA)
  ui.textColored('RICH GUY LOSO', rgbm(1, 1, 1, 1))
  ui.sameLine()
  ui.textColored('  LIVE FROM NYC', COLOR_MUTED)
  ui.separator()

  if not licensed then
    ui.textColored('LOCKED', rgbm(1.00, 0.29, 0.29, 1))
    ui.textWrapped('This radio was created by RichGuyLos and is locked to his '
      .. 'servers. It will not run anywhere else.')
    ui.separator()
    -- Shown so an authorised server that fails to match can be identified and
    -- added to the build. It leaks nothing: this is the public address anyone
    -- already types in to connect.
    ui.textColored('Either this server is not authorised, or this build has '
      .. 'passed its expiry date and a new one is needed from the author.',
      rgbm(0.46, 0.58, 0.72, 1))
    ui.separator()
    -- Shown so an authorised server that fails to match can be identified and
    -- added to the build. It leaks nothing: this is the public address anyone
    -- already types in to connect.
    ui.textColored('This server reports:', rgbm(0.46, 0.58, 0.72, 1))
    for _, ident in ipairs(serverIdents()) do
      ui.text('  ' .. ident)
    end
    ui.text('  date ' .. os.date('%Y-%m-%d'))
    return false
  end

  local station = currentStation()
  local displayAt = ui.getCursor()
  local displayWidth = ui.availableSpaceX()
  local displayHeight = math.max(DISPLAY_MIN_HEIGHT,
    math.min(DISPLAY_MAX_HEIGHT, math.floor(displayWidth / ARTWORK_ASPECT)))
  local displaySize = vec2(displayWidth, displayHeight)
  local overlaid = drawDisplay(displayAt, displaySize, station,
                               powered and status == 'PLAYING')

  -- drawDisplay positions its text absolutely, which leaves the cursor part
  -- way up the display. Put it back and claim the space properly, or every
  -- row below here draws on top of the artwork.
  ui.setCursor(displayAt)
  ui.dummy(displaySize)

  if not overlaid then
    -- Display too short to carry the text: put it underneath instead.
    ui.textColored(station.frequency, COLOR_CYAN)
    ui.sameLine()
    ui.textColored('  ' .. station.name, rgbm(1, 1, 1, 1))
    ui.sameLine()
    ui.textColored('  ' .. shownStatus(), shownStatus() == 'PLAYING' and COLOR_LIME or COLOR_MUTED)
  end

  ui.offsetCursor(vec2(0, 6))
  ui.textColored('TAP A STATION', COLOR_MUTED)

  for i, item in ipairs(stations) do
    local prefix = selected == i and '>  ' or '   '
    if ui.selectable(prefix .. item.frequency .. '   ' .. item.name, selected == i) then
      passes = 0
      claimAudio()
      tune(i, 1)
    end
  end

  ui.separator()
  ui.textColored('VOLUME', COLOR_CYAN)
  ui.sameLine()
  ui.textColored(string.format('%d%%', math.floor(volume * 100 + 0.5)), COLOR_MUTED)
  local nextVolume = ui.slider('##rglRadioVolume', volume * 100, 0, 100, '%.0f%%') / 100
  if math.abs(nextVolume - volume) > 0.001 then
    volume = nextVolume
    applyVolume()
  end

  -- Fixed button widths clipped the last button once the panel got narrow, so
  -- divide up whatever width there actually is.
  local gap = 4
  local stepWidth = 26
  local wideWidth = math.max(40, (ui.availableSpaceX() - stepWidth * 2 - gap * 3) / 2)
  if ui.button('<<', vec2(stepWidth, 26)) then
    stationStep(-1)
  end
  ui.sameLine(0, gap)
  if ui.button(powered and 'POWER OFF' or 'POWER ON', vec2(wideWidth, 26)) then
    togglePower()
  end
  ui.sameLine(0, gap)
  if ui.button(muted and 'UNMUTE' or 'MUTE', vec2(wideWidth, 26)) then
    muted = not muted
    applyVolume()
  end
  ui.sameLine(0, gap)
  if ui.button('>>', vec2(stepWidth, 26)) then
    stationStep(1)
  end

  if ui.button('RECONNECT', vec2(ui.availableSpaceX(), 24)) then
    passes = 0
    claimAudio()
    tune(selected, 1)
  end

  ui.offsetCursor(vec2(-14, 0))
  return false
end

-- Deliberately NOT registered as an online extra. ui.registerOnlineExtra is
-- what puts an entry in the chat / lightbulb menu, and there is no flag to
-- register without one. Drawing our own window from script.drawUI keeps the
-- radio entirely out of that menu.
--
-- It sits collapsed as a small BTA badge by default and expands to the full
-- panel when clicked, so it is reachable - a player who wants the radio off
-- can still stop it - without permanently occupying part of the screen.

local PANEL_SIZE = vec2(292, 512)
local BADGE_SIZE = vec2(124, 36)
local PANEL_AT = vec2(24, 200)

local panelOpen = false

function script.drawUI()
  if not licensed then return end

  if not panelOpen then
    ui.toolWindow('rglRadioBadge', PANEL_AT, BADGE_SIZE, true, true, function ()
      ui.drawRectFilled(vec2(0, 0), BADGE_SIZE, rgbm(0.02, 0.03, 0.06, 0.85), 6)
      if ARTWORK_URL ~= '' and ui.isImageReady(ARTWORK_URL) then
        ui.drawImage(ARTWORK_URL, vec2(2, 2), BADGE_SIZE - vec2(2, 2),
                     rgbm(1, 1, 1, 1), vec2(0, 0), vec2(1, 1), ui.ImageFit.Fill)
      else
        ui.setCursor(vec2(10, 9))
        ui.textColored('B T A   RADIO', COLOR_CYAN)
      end
      ui.drawRect(vec2(0, 0), BADGE_SIZE, rgbm(0.16, 0.75, 1.00, 0.5), 6, 0, 1)

      -- An invisible button over the whole badge, so the click target is the
      -- badge itself rather than whatever happens to be under the cursor.
      ui.setCursor(vec2(0, 0))
      if ui.invisibleButton('rglRadioBadgeHit', BADGE_SIZE) then
        panelOpen = true
      end
    end)
    return
  end

  ui.toolWindow('rglRadioPanel', PANEL_AT, PANEL_SIZE, false, true, function ()
    radioUI()
    ui.offsetCursor(vec2(0, 4))
    if ui.button('HIDE', vec2(ui.availableSpaceX(), 22)) then
      panelOpen = false
    end
  end)
end

function script.update(dt)
  if not licensed then return end

  tickDisplay(dt)

  -- Hand over to the car's own radio while it plays, and take back when it
  -- stops. Pause rather than mute: this player is created with rawOutput = true
  -- and goes straight to the Windows device, where setMuted alone did not
  -- actually silence it and both radios were audible together. pause() is what
  -- STOP already relies on.
  local carNow = carRadio ~= nil and carRadio.playing ~= 0
  if carNow ~= carRadioPlaying then
    carRadioPlaying = carNow
    if player then
      if carNow then
        player:pause()
      elseif powered then
        player:play()
      end
    end
    applyVolume()
  end

  statusTimer = statusTimer + dt
  sinceTune = sinceTune + dt

  -- Start for every joining player from the always-running online-script update
  -- loop. No radio window interaction is required.
  if not mediaCheckStarted then
    autoStartTimer = autoStartTimer + dt
    if autoStartTimer >= AUTO_START_DELAY then
      mediaCheckStarted = true
      status = 'STARTING'
      statusDetail = 'Starting radio automatically'
      ui.MediaPlayer.supportedAsync(function (supported)
        if supported then
          passes = 0
          tune(selected, 1)
        else
          status = 'UNAVAILABLE'
          statusDetail = 'CSP native media playback is not supported on this PC'
          powered = false
        end
      end)
    end
  end

  if not player or not powered then return end

  -- `playing()` only describes the requested playback state. Require a decoded
  -- audio track as well so a failed stream cannot be shown as PLAYING.
  if player:playing() and player:hasAudio() then
    if not toastShown then
      toastShown = true
      ui.toast(ui.Icons.Radio, 'RichGuyLos Radio Station started automatically. Open Chat > lightbulb for controls.')
    end
    -- Audio is flowing, so a stream that dies hours from now still gets a full
    -- set of retries rather than inheriting an old failure count.
    passes = 0
    if statusTimer >= 0.5 then
      statusTimer = 0
      status = muted and 'MUTED' or 'PLAYING'
      statusDetail = currentStation().name ..
        (urlIndex > 1 and ' backup stream' or ' live stream')
    end
    return
  end

  if sinceTune < CONNECT_TIMEOUT then
    if statusTimer >= 0.5 then
      statusTimer = 0
      status = player:hasAudio() and 'BUFFERING' or 'CONNECTING'
      statusDetail = 'Opening ' .. currentStation().name
    end
    return
  end

  -- Silent past the timeout: move to this station's next URL, and once the list
  -- is exhausted start it over until MAX_PASSES.
  local station = currentStation()
  if station.urls[urlIndex + 1] then
    tune(selected, urlIndex + 1)
  else
    passes = passes + 1
    if passes >= MAX_PASSES then
      status = 'UNAVAILABLE'
      statusDetail = station.name .. ' is not responding - pick another station'
      powered = false
      player:pause()
    else
      tune(selected, 1)
    end
  end
end
